search.query:
index::* sourcetype="microsoft:userRegistrationDetails" userPrincipalName="$tkn_link$"
| dedup userPrincipalName 
| mvexpand systemPreferredAuthenticationMethods{}
| search systemPreferredAuthenticationMethods{}!=""
| stats count as "User Count" by systemPreferredAuthenticationMethods{} 
| transpose 0 header_field=systemPreferredAuthenticationMethods{} 
| rename column as "Preferred Authentication Methods"
| eval "Preferred Authentication Methods"=""

index=* sourcetype="microsoft:userRegistrationDetails"
| table DateTime, _time, userPrincipalName, userDisplayName, userType, isSsprRegistered, isSsprCapable, isMfaRegistered, isPasswordlessCapable, methodsRegistered{}, systemPreferredAuthenticationMethods{}, userPreferredMethodForSecondaryAuthentication
| fillnull value="-"
| mvexpand methodsRegistered{}
| table methodsRegistered{}
| dedup methodsRegistered{}

index=* sourcetype="microsoft:userRegistrationDetails"
| table DateTime, _time, userPrincipalName, userDisplayName, userType, isSsprRegistered, isSsprCapable, isMfaRegistered, isPasswordlessCapable, MethodsRegistered, systemPreferredAuthenticationMethods{}, userPreferredMethodForSecondaryAuthentication
| fillnull value="-"
| table systemPreferredAuthenticationMethods{}
| dedup systemPreferredAuthenticationMethods{}
